1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>Vocabulary SRS — Islam Academy</title>
7	<link rel="stylesheet" href="../assets/css/academy.css">
8	<link rel="stylesheet" href="../assets/css/components.css">
9	<style>
10	/* === RESPONSIVE FIX (auto-injected) === */
11	@media (max-width: 768px) {
12	  /* Prevent horizontal overflow on body */
13	  body, html { max-width: 100vw; overflow-x: hidden; }
14	  
15	  /* Tables scroll horizontally instead of overflowing */
16	  table { max-width: 100%; overflow-x: auto; display: block; }
17	  
18	  /* Grain overlays — constrain to viewport */
19	  .grain-overlay { width: 100vw !important; max-width: 100vw !important; left: 0 !important; right: 0 !important; }
20	  
21	  /* Chat pages — make responsive */
22	  .chat_page, .page_body { max-width: 100vw !important; width: 100% !important; }
23	  .content { max-width: 100vw !important; width: 100% !important; }
24	  .history { max-width: 100% !important; }
25	  .message { max-width: 100% !important; word-wrap: break-word; overflow-wrap: break-word; }
26	  .body { max-width: 100% !important; }
27	  .media.clearfix { max-width: 100% !important; }
28	  
29	  /* Nebula/glows — constrain */
30	  .nebula, .glow { max-width: 100vw !important; }
31	  
32	  /* Orb animations — constrain */
33	  .orb { max-width: 100vw !important; }
34	  
35	  /* Larger touch targets */
36	  a, button, input, select, textarea, [role="button"], [onclick] {
37	    min-height: 44px;
38	    min-width: 44px;
39	  }
40	  
41	  /* Fix small text */
42	  body { font-size: max(14px, inherit); }
43	  
44	  /* Chips/buttons wrap */
45	  .chips { flex-wrap: wrap !important; overflow: hidden !important; }
46	  .chip { flex-shrink: 1 !important; }
47	  
48	  /* Reminder bars — constrain */
49	  .due-date-reminder { max-width: 100vw !important; width: 100% !important; left: 0 !important; right: 0 !important; }
50	  
51	  /* Timer/countdown blocks */
52	  .timer, .timer-unit, .moon-countdown { max-width: 100% !important; }
53	  
54	  /* KPI tables, data tables */
55	  .kpi-table, .cyber-table, .org-table, .bp-table, .ptrack { max-width: 100% !important; overflow-x: auto; display: block; }
56	  
57	  /* Notebook/book pages */
58	  .page.cover, .page { max-width: 100% !important; width: 100% !important; }
59	  
60	  /* Tape tracks — hide overflow on mobile */
61	  .tape-track { overflow: hidden !important; }
62	  
63	  /* Banner/topbar */
64	  .topbar-right { max-width: 100% !important; flex-wrap: wrap; }
65	}
66	</style>
67	</head>
68	<body>
69	<header class="site-header"><div class="header-inner">
70	  <a class="brand" href="../index.html"><div class="brand-mark">ق</div>
71	  <div class="brand-name">Islam Academy<small>Arabic · Quran · Tajweed</small></div></a>
72	  <nav class="nav" id="main-nav"></nav>
73	</div></header>
74	
75	<main class="container">
76	  <h1 class="page-title">🗂️ Vocabulary — Spaced Repetition <span class="help-trigger">?<div class="help-tip"><h4>Vocabulary SRS</h4><p>Learn Quran & Arabic vocabulary using spaced repetition. Cards you find hard come back sooner; easy ones drift into long-term memory.</p><ul><li><strong>📚 Study</strong> — Flip flashcards and rate difficulty</li><li><strong>📋 Browse</strong> — See all words in the deck</li><li><strong>🌳 Root Explorer</strong> — Discover Arabic root families</li><li><strong>📊 Frequency</strong> — See word frequency charts</li><li><strong>🧩 Root Quiz</strong> — Guess words from the same root</li></ul></div></span></h1>
77	  <p class="page-sub">Flashcards with an SM-2 scheduling engine. Cards you find hard come back sooner; easy ones drift into long-term memory.</p>
78	
79	  <div class="reader-toolbar" id="deck-picker"></div>
80	  <div id="stats-line" style="margin-bottom:14px;color:var(--ink-soft);font-size:13.5px"></div>
81	
82	  <div style="display:flex;gap:8px;margin-bottom:16px;flex-wrap:wrap">
83	    <button class="btn gold small" id="mode-study" onclick="setMode('study')">📚 Study</button>
84	    <button class="btn ghost small" id="mode-browse" onclick="setMode('browse')">📋 Browse All</button>
85	    <button class="btn ghost small" id="mode-root" onclick="setMode('root')">🌳 Root Explorer</button>
86	    <button class="btn ghost small" id="mode-freq" onclick="setMode('freq')">📊 Frequency</button>
87	    <button class="btn ghost small" id="mode-quiz" onclick="setMode('quiz')">🧩 Root Quiz</button>
88	  </div>
89	
90	  <div id="study-area"></div>
91	  <div id="browse-area" style="display:none"></div>
92	  <div id="root-area" style="display:none"></div>
93	  <div id="freq-area" style="display:none"></div>
94	  <div id="quiz-area" style="display:none"></div>
95	</main>
96	
97	<footer class="site-footer">Islam Academy — Vocabulary</footer>
98	<script src="../assets/js/app.js"></script>
99	<script src="../assets/js/nav.js"></script>
100	<script>
101	(async function () {
102	  const { el } = Academy;
103	  let decks;
104	  try {
105	    decks = await Academy.fetchJSON("../data/curriculum/decks.json");
106	  } catch(e) {
107	    document.getElementById("study-area").innerHTML = '<div class="card"><p class="sub">Could not load vocabulary. Serve via HTTP not file://.</p></div>';
108	    return;
109	  }
110	  const picker = document.getElementById("deck-picker");
111	  const statsLine = document.getElementById("stats-line");
112	  const area = document.getElementById("study-area");
113	  let deckId = Object.keys(decks)[0];
114	
115	  Object.entries(decks).forEach(([id, d]) => {
116	    picker.append(el("button", {class:"btn small ghost", "data-deck":id, onclick:()=>{deckId=id; start();}}, d.title));
117	  });
118	
119	  function cardKey(w) { return deckId + "::" + w.ar; }
120	
121	  function start() {
122	    picker.querySelectorAll("button").forEach(b => {
123	      b.classList.toggle("gold", b.dataset.deck === deckId);
124	      b.classList.toggle("ghost", b.dataset.deck !== deckId);
125	    });
126	    const deck = decks[deckId];
127	    const keys = deck.words.map(cardKey);
128	    const st = Academy.srsStats(keys);
129	    statsLine.textContent = deck.desc + " — " + st.total + " cards · " + st.due + " due now · " + st.mature + " mature";
130	    buildQueue();
131	  }
132	
133	  let queue = [], sessionDone = 0;
134	  function buildQueue() {
135	    const deck = decks[deckId];
136	    const dueWords = deck.words.filter(w => Academy.dueCards([cardKey(w)]).length > 0);
137	    queue = Academy.shuffle(dueWords).slice(0, 20);
138	    if (queue.length === 0) {
139	      area.innerHTML = "";
140	      area.append(el("div", {class:"card", style:"text-align:center;padding:40px"},
141	        el("div", {style:"font-size:44px"}, "🌴"),
142	        el("h3", null, "Nothing due in this deck"),
143	        el("p", {class:"sub"}, "Come back when cards mature, or review another deck."),
144	        el("button", {class:"btn gold", onclick:()=>{ queue = Academy.shuffle(decks[deckId].words).slice(0,10); next(); }}, "Cram 10 anyway")));
145	      return;
146	    }
147	    sessionDone = 0;
148	    next();
149	  }
150	
151	  function next() {
152	    area.innerHTML = "";
153	    if (queue.length === 0) {
154	      area.append(el("div", {class:"card", style:"text-align:center;padding:40px"},
155	        el("div", {style:"font-size:44px"}, "✅"),
156	        el("h3", null, "Session complete"),
157	        el("p", {class:"sub"}, sessionDone + " reviews · +" + sessionDone * 2 + " XP"),
158	        el("button", {class:"btn gold", onclick:start}, "Continue")));
159	      return;
160	    }
161	    const w = queue[0];
162	    let flipped = false;
163	
164	    // Show frequency badge if available
165	    const freqBadge = w.freq ? el("div", {class:"freq-badge", style:"position:absolute;top:12px;left:12px;background:var(--gold);color:#fff;border-radius:12px;padding:2px 8px;font-size:11px;font-weight:600"}, "×" + w.freq) : null;
166	
167	    const frontAr = el("div", {class:"front-ar"}, w.ar);
168	    const tapHint = el("div", {class:"tap-hint"}, "tap to reveal");
169	    const front = el("div", {class:"flashcard-front"},
170	      freqBadge,
171	      frontAr,
172	      tapHint);
173	    // Build back content with root decomposition
174	    const backChildren = [
175	      el("div", {class:"back-en"}, w.en),
176	      el("div", {class:"translit"}, w.tl),
177	    ];
178	    if (w.freq) backChildren.push(el("div", {style:"font-size:12px;color:var(--gold);margin-top:6px"}, "Appears " + w.freq + "× in the Quran"));
179	    if (w.root) {
180	      const rootParts = w.root.split(".");
181	      const rootDisplay = rootParts.map((r, i) => {
182	        const colors = ["#dc2626", "#2563eb", "#16a34a"];
183	        return el("span", {style:"display:inline-block;width:40px;height:40px;line-height:40px;border-radius:50%;font-size:22px;font-weight:700;margin:0 3px;color:#fff;background:" + colors[i]}, r);
184	      });
185	      backChildren.push(el("div", {class:"root-decomp", style:"margin-top:12px;padding-top:12px;border-top:1px dashed var(--line)"},
186	        el("div", {style:"font-size:11px;color:var(--ink-soft);text-transform:uppercase;letter-spacing:1px;margin-bottom:6px"}, "Root (جذر)"),
187	        el("div", {style:"display:flex;flex-direction:row-reverse;align-items:center;justify-content:center;gap:4px"},
188	          el("div", {style:"display:flex;flex-direction:row-reverse;gap:3px"}, ...rootDisplay),
189	          el("span", {style:"font-size:11px;color:var(--ink-soft)"}, w.pattern || "")
190	        ),
191	        el("div", {style:"font-size:11px;color:var(--ink-soft);margin-top:6px;font-style:italic"}, "Root: " + w.root + " — Pattern: " + (w.pattern || "—"))
192	      ));
193	    }
194	    const back = el("div", {style:"display:none"}, ...backChildren);
195	
196	    const card = el("div", {class:"flashcard", onclick:(e)=>{
197	      if (e.target.closest(".speaker-btn") || e.target.closest(".grade-row")) return;
198	      flipped = !flipped;
199	      if (freqBadge) freqBadge.style.display = flipped ? "none" : "";
200	      tapHint.style.display = flipped ? "none" : "";
201	      back.style.display = flipped ? "" : "none";
202	      card.classList.toggle("flipped", flipped);
203	    }}, front, back, el("button", {class:"speaker-btn", style:"position:absolute;top:12px;right:12px",
204	      onclick:(e)=>{ e.stopPropagation(); speakWord(w); }}, "🔊"));
205	
206	    const grades = el("div", {class:"grade-row", style:"display:none"},
207	      gradeBtn("Again", "again", 0), gradeBtn("Hard", "hard", 1), gradeBtn("Good", "good", 2), gradeBtn("Easy", "easy", 3));
208	
209	    function gradeBtn(label, cls, g) {
210	      return el("button", {class:"grade-btn " + cls, onclick:(e)=>{
211	        e.stopPropagation();
212	        Academy.reviewCard(cardKey(w), g);
213	        Academy.addXP(2);
214	        sessionDone++;
215	        queue.shift();
216	        next();
217	      }}, label);
218	    }
219	
220	    // reveal grades on flip
221	    card.addEventListener("click", () => { if (flipped) grades.style.display = ""; });
222	
223	    area.append(
224	      el("p", {style:"color:var(--ink-soft);font-size:13px;margin:0 0 10px;display:flex;align-items:center;gap:6px"},
225	        queue.length + " left in this session",
226	        el("span", {class:"help-trigger", style:"font-size:10px;width:16px;height:16px"}, "?",
227	          el("div", {class:"help-tip"},
228	            el("h4", null, "Flashcard Study"),
229	            el("p", null, "Tap the card to flip and reveal the answer."),
230	            el("ul", null,
231	              el("li", null, "🔊 ", el("span", {class:"key"}, "Listen"), " — hear pronunciation"),
232	              el("li", null, "Again ", el("span", {class:"key"}, "0"), " — didn't know, review soon"),
233	              el("li", null, "Hard ", el("span", {class:"key"}, "1"), " — knew but struggled"),
234	              el("li", null, "Good ", el("span", {class:"key"}, "2"), " — remembered correctly"),
235	              el("li", null, "Easy ", el("span", {class:"key"}, "3"), " — instant recall"),
236	            ),
237	            el("p", null, "Cards rated 'Again' return sooner. 'Easy' cards drift into long-term memory.")
238	          )
239	        )
240	      ),
241	      card, grades
242	    );
243	  }
244	
245	  function speakWord(w) {
246	    // Use the universal speakArabic which tries local MP3, then Web Speech API, then visual feedback
247	    Academy.speakArabic(w.ar);
248	  }
249	
250	  let currentMode = 'study';
251	  window.setMode = function(m) {
252	    currentMode = m;
253	    document.getElementById('mode-study').className = m==='study' ? 'btn gold small' : 'btn ghost small';
254	    document.getElementById('mode-browse').className = m==='browse' ? 'btn gold small' : 'btn ghost small';
255	    document.getElementById('mode-root').className = m==='root' ? 'btn gold small' : 'btn ghost small';
256	    document.getElementById('mode-freq').className = m==='freq' ? 'btn gold small' : 'btn ghost small';
257	    document.getElementById('mode-quiz').className = m==='quiz' ? 'btn gold small' : 'btn ghost small';
258	    document.getElementById('study-area').style.display = m==='study' ? '' : 'none';
259	    document.getElementById('browse-area').style.display = m==='browse' ? '' : 'none';
260	    document.getElementById('root-area').style.display = m==='root' ? '' : 'none';
261	    document.getElementById('freq-area').style.display = m==='freq' ? '' : 'none';
262	    document.getElementById('quiz-area').style.display = m==='quiz' ? '' : 'none';
263	    if (m==='browse') renderBrowse();
264	    if (m==='root') renderRootExplorer();
265	    if (m==='freq') renderFrequency();
266	    if (m==='quiz') startRootQuiz();
267	    if (m==='study') buildQueue();
268	  };
269	
270	  function renderBrowse() {
271	    const deck = decks[deckId];
272	    const browse = document.getElementById('browse-area');
273	    browse.innerHTML = '';
274	    const grid = el('div', {style:'display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px'});
275	    deck.words.forEach((w, i) => {
276	      const row = el('div', {class:'card', style:'padding:12px;display:flex;align-items:center;gap:10px;cursor:pointer'},
277	        el('div', {style:'min-width:36px;height:36px;border-radius:50%;background:var(--gold);color:#fff;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700'}, w.freq ? '×'+w.freq : (i+1)),
278	        el('div', {style:'flex:1'},
279	          el('div', {class:'ar', style:'font-size:22px;font-weight:600;line-height:1.3'}, w.ar),
280	          el('div', {style:'font-size:13px;color:var(--ink-soft)'}, w.en),
281	          el('div', {style:'font-size:11px;color:var(--ink-soft);font-style:italic'}, w.tl)
282	        ),
283	        el('button', {class:'speaker-btn', style:'background:none;border:none;cursor:pointer;font-size:20px', onclick:(e)=>{ e.stopPropagation(); speakWord(w); }}, '🔊')
284	      );
285	      grid.append(row);
286	    });
287	    browse.append(
288	      el('h3', {style:'margin-bottom:10px;display:flex;align-items:center;gap:6px'},
289	        deck.title + ' — ' + deck.words.length + ' words',
290	        el('span', {class:'help-trigger', style:'font-size:10px;width:16px;height:16px'}, '?',
291	          el('div', {class:'help-tip'},
292	            el('h4', null, 'Browse Mode'),
293	            el('p', null, 'View all words in the current deck sorted by frequency or alphabetically.'),
294	            el('ul', null,
295	              el('li', null, '🔊 — tap to hear pronunciation'),
296	              el('li', null, 'Gold circles show frequency (×2699 = appears 2699× in Quran)'),
297	              el('li', null, 'Switch decks using the buttons at the top'),
298	            )
299	          )
300	        )
301	      ),
302	      grid
303	    );
304	  }
305	
306	  function renderRootExplorer() {
307	    const deck = decks[deckId];
308	    const rootArea = document.getElementById('root-area');
309	    rootArea.innerHTML = '';
310	
311	    // Group words by root
312	    const rootGroups = {};
313	    const noRoot = [];
314	    deck.words.forEach(w => {
315	      if (w.root) {
316	        if (!rootGroups[w.root]) rootGroups[w.root] = { root: w.root, words: [] };
317	        rootGroups[w.root].words.push(w);
318	      } else {
319	        noRoot.push(w);
320	      }
321	    });
322	
323	    // Sort roots by number of derived words (descending)
324	    const sorted = Object.values(rootGroups).sort((a, b) => b.words.length - a.words.length);
325	
326	    // Summary stats
327	    const totalRoots = sorted.length;
328	    const totalWordsWithRoot = sorted.reduce((s, g) => s + g.words.length, 0);
329	    rootArea.append(el('div', {style:'margin-bottom:16px;padding:14px;background:var(--cream);border-radius:12px'},
330	      el('div', {style:'font-weight:700;font-size:15px;margin-bottom:4px;display:flex;align-items:center;gap:6px'},
331	        '🌳 Root System Overview',
332	        el('span', {class:'help-trigger', style:'font-size:10px;width:16px;height:16px'}, '?',
333	          el('div', {class:'help-tip'},
334	            el('h4', null, 'Arabic Root System'),
335	            el('p', null, 'Most Arabic words derive from 3-letter roots (جذر) that carry a core meaning.'),
336	            el('ul', null,
337	              el('li', null, '🔴🔵🟢 — Each color = one root letter'),
338	              el('li', null, 'Words sharing a root are related in meaning'),
339	              el('li', null, 'Patterns (وزن) change the meaning: verb → noun → adjective'),
340	            ),
341	            el('p', null, 'Example: Root ك.ت.ب (writing) → كتاب (book), كاتب (writer), مكتوب (written)')
342	          )
343	        )
344	      ),
345	      el('div', {style:'font-size:13px;color:var(--ink-soft)'},
346	        totalRoots + ' unique roots · ' + totalWordsWithRoot + ' words with roots · ' + noRoot.length + ' particles/irregulars'),
347	      el('div', {style:'font-size:12px;color:var(--ink-soft);margin-top:6px'},
348	        'Arabic derives from ~10,000 trilateral roots. Each root carries a core meaning that expands through patterns (أوزان).')
349	    ));
350	
351	    // Render each root group
352	    sorted.forEach(group => {
353	      const rootParts = group.root.split('.');
354	      const colors = ['#dc2626', '#2563eb', '#16a34a'];
355	      const rootSpans = rootParts.map((r, i) =>
356	        el('span', {style:'display:inline-block;width:32px;height:32px;line-height:32px;border-radius:50%;font-size:18px;font-weight:700;color:#fff;background:' + colors[i], title: ['1st root letter (فَعْل)', '2nd root letter (فَعْل)', '3rd root letter (فَعْل)'][i]}, r)
357	      );
358	
359	      const wordCards = group.words.map(w => {
360	        const card = el('div', {class:'root-word-card', style:'display:flex;align-items:center;gap:8px;padding:8px 10px;background:var(--paper);border:1px solid var(--line);border-radius:8px;cursor:pointer'},
361	          el('div', {class:'ar', style:'font-size:20px;font-weight:600'}, w.ar),
362	          el('div', {style:'flex:1'},
363	            el('div', {style:'font-size:12px;color:var(--ink-soft)'}, w.en),
364	            el('div', {style:'font-size:11px;color:var(--gold-500);font-style:italic'}, w.pattern || '')
365	          ),
366	          el('button', {class:'speaker-btn', style:'background:none;border:none;cursor:pointer;font-size:16px', onclick: (e) => { e.stopPropagation(); speakWord(w); }}, '🔊')
367	        );
368	        return card;
369	      });
370	
371	      const groupEl = el('div', {class:'card', style:'margin-bottom:12px;padding:16px'},
372	        el('div', {style:'display:flex;align-items:center;gap:12px;margin-bottom:10px'},
373	          el('div', {style:'display:flex;flex-direction:row-reverse;gap:3px'}, ...rootSpans),
374	          el('span', {style:'font-size:14px;font-weight:700;color:var(--ink)'}, 'Root: ' + group.root.replace(/\./g, ' ')),
375	          el('span', {style:'font-size:12px;color:var(--ink-soft);margin-left:auto'}, group.words.length + ' word' + (group.words.length > 1 ? 's' : ''))
376	        ),
377	        el('div', {style:'display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:6px'}, ...wordCards)
378	      );
379	
380	      rootArea.append(groupEl);
381	    });
382	
383	    // Show particles section
384	    if (noRoot.length > 0) {
385	      rootArea.append(el('div', {class:'card', style:'margin-top:16px;padding:16px'},
386	        el('div', {style:'font-weight:700;margin-bottom:8px'}, '📝 Particles & Irregulars (' + noRoot.length + ' words)'),
387	        el('div', {style:'font-size:12px;color:var(--ink-soft);margin-bottom:10px'}, 'These words are particles (حروف), pronouns, or proper nouns that don\'t follow the standard root system.'),
388	        el('div', {style:'display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:6px'},
389	          ...noRoot.slice(0, 40).map(w => el('div', {style:'padding:6px 8px;background:var(--cream);border-radius:6px;font-size:13px'},
390	            el('span', {class:'ar', style:'font-size:16px;font-weight:600'}, w.ar),
391	            el('span', {style:'color:var(--ink-soft);margin-left:4px'}, ' — ' + w.en)
392	          ))
393	        )
394	      ));
395	    }
396	  }
397	
398	  function renderFrequency() {
399	    const deck = decks[deckId];
400	    const freqArea = document.getElementById('freq-area');
401	    freqArea.innerHTML = '';
402	
403	    const wordsWithFreq = deck.words.filter(w => w.freq && w.freq > 0);
404	    if (wordsWithFreq.length === 0) {
405	      freqArea.append(el('div', {class:'card', style:'text-align:center;padding:40px'},
406	        el('div', {style:'font-size:44px'}, '📊'),
407	        el('h3', null, 'No frequency data'),
408	        el('p', {class:'sub'}, 'Switch to a Quran vocabulary deck to see frequency charts.')));
409	      return;
410	    }
411	
412	    const sorted = [...wordsWithFreq].sort((a,b) => b.freq - a.freq);
413	    const maxFreq = sorted[0].freq;
414	    const totalFreq = sorted.reduce((s,w) => s + w.freq, 0);
415	
