file.content:
const w = queue[0];
let flipped = false;

// Show frequency badge if available
const freqBadge = w.freq ? el("div", {class:"freq-badge", style:"position:absolute;top:12px;left:12px;background:var(--gold);color:#fff;border-radius:12px;padding:2px 8px;font-size:11px;font-weight:600"}, "×" + w.freq) : null;

const frontAr = el("div", {class:"front-ar"}, w.ar);
const tapHint = el("div", {class:"tap-hint"}, "tap to reveal");
const front = el("div", {class:"flashcard-front"},
  freqBadge,
  frontAr,
  tapHint);
// Build back content with root decomposition
const backChildren = [
  el("div", {class:"back-en"}, w.en),
  el("div", {class:"translit"}, w.tl),
];
if (w.freq) backChildren.push(el("div", {style:"font-size:12px;color:var(--gold);margin-top:6px"}, "Appears " + w.freq + "× in the Quran"));
if (w.root) {
  const rootParts = w.root.split(".");
  const rootDisplay = rootParts.map((r, i) => {
    const colors = ["#dc2626", "#2563eb", "#16a34a"];
    return el("span", {style:"display:inline-block;width:40px;height:40px;line-height:40px;border-radius:50%;font-size:22px;font-weight:700;margin:0 3px;color:#fff;background:" + colors[i]}, r);
  });
  backChildren.push(el("div", {class:"root-decomp", style:"margin-top:12px;padding-top:12px;border-top:1px dashed var(--line)"},
    el("div", {style:"font-size:11px;color:var(--ink-soft);text-transform:uppercase;letter-spacing:1px;margin-bottom:6px"}, "Root (جذر)"),
    el("div", {style:"display:flex;flex-direction:row-reverse;align-items:center;justify-content:center;gap:4px"},
      el("div", {style:"display:flex;flex-direction:row-reverse;gap:3px"}, ...rootDisplay),
      el("span", {style:"font-size:11px;color:var(--ink-soft)"}, w.pattern || "")
    ),
    el("div", {style:"font-size:11px;color:var(--ink-soft);margin-top:6px;font-style:italic"}, "Root: " + w.root + " — Pattern: " + (w.pattern || "—"))
  ));
}
const back = el("div", {style:"display:none"}, ...backChildren);

const card = el("div", {class:"flashcard", onclick:(e)=>{
  if (e.target.closest(".speaker-btn") || e.target.closest(".grade-row")) return;
  flipped = !flipped;
  if (freqBadge) freqBadge.style.display = flipped ? "none" : "";
  tapHint.style.display = flipped ? "none" : "";
  back.style.display = flipped ? "" : "none";
  card.classList.toggle("flipped", flipped);
}}, front, back, el("button", {class:"speaker-btn", style:"position:absolute;top:12px;right:12px",
  onclick:(e)=>{ e.stopPropagation(); speakWord(w); }}, "🔊"));

const grades = el("div", {class:"grade-row", style:"display:none"},
  gradeBtn("Again", "again", 0), gradeBtn("Hard", "hard", 1), gradeBtn("Good", "good", 2), gradeBtn("Easy", "easy", 3));

function gradeBtn(label, cls, g) {
  return el("button", {class:"grade-btn " + cls, onclick:(e)=>{
    e.stopPropagation();
    Academy.reviewCard(cardKey(w), g);
    Academy.addXP(2);
    sessionDone++;
    queue.shift();
    next();
  }}, label);
}

// reveal grades on flip

